"""Nederlands — deugden (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("Wat moet volgens een hadith overgeleverd door imam al-Bukhari iemand die in Allah en de Laatste Dag gelooft met zijn spreken doen?", ["Het goede zeggen of zwijgen", "Luid spreken", "Nooit spreken", "Geruchten herhalen"], "De Profeet ﷺ zei: «Wie in Allah en de Laatste Dag gelooft, laat hij het goede zeggen of zwijgen.»"),
"virtues_002": ("Wie moet een gelovige volgens diezelfde hadith nog meer eren, behalve zijn gast?", ["Zijn buur", "Zijn koopman", "Zijn rivaal", "Een vreemde"], "De hadith vervolgt: «…en wie in Allah en de Laatste Dag gelooft, laat hij zijn buur eren.»"),
"virtues_003": ("Diezelfde hadith noemt ook het eren van wie, wanneer die bij iemand thuis komt?", ["De gast", "Alleen de buur", "De koopman", "Een verre onbekende reiziger"], "De volledige hadith zegt: «…wie in Allah en de Laatste Dag gelooft, laat hij zijn gast eren.»"),
"virtues_004": ("Volgens een authentieke hadith is het geloof van een gelovige niet volledig totdat hij voor zijn broeder wenst wat hij wenst voor…", ["zichzelf", "zijn rijkdom", "alleen zijn familie", "zijn land"], "De Profeet ﷺ zei: «Niemand van jullie gelooft werkelijk totdat hij voor zijn broeder wenst wat hij voor zichzelf wenst.»"),
"virtues_005": ("Volgens een authentieke hadith is de ware moslim degene voor wiens tong en ___ anderen veilig zijn.", ["hand", "rijkdom", "blik", "stem"], "De Profeet ﷺ zei: «De moslim is degene voor wiens tong en hand de andere moslims veilig zijn.»"),
"virtues_006": ("De Koran gebiedt goedheid jegens de ouders en verbiedt zelfs welk woord van ergernis tegen hen te zeggen?", ["«Oef» (een geluid van ongeduld)", "«Nee»", "«Genoeg»", "«Wacht»"], "De Koran vraagt de grootste goedheid jegens de ouders en verbiedt zelfs het geringste woord van minachting."),
"virtues_007": ("Waarmee vergelijkt de Koran kwaadsprekerij (kwaad spreken over een afwezige)?", ["Met het eten van het vlees van je dode broeder", "Met het drinken van zout water", "Met lopen in het donker", "Met zaaien in zand"], "«Zou een van jullie het vlees van zijn dode broeder willen eten? Jullie zouden ervan walgen!»: zo lelijk is kwaadsprekerij."),
"virtues_008": ("Hoe beschrijft de Koran de relatie tussen de gelovigen?", ["Zij zijn broeders", "Zij zijn concurrenten", "Zij zijn vreemden", "Zij zijn zakenpartners"], "«De gelovigen zijn slechts broeders, sticht dus vrede tussen jullie twee broeders.»"),
"virtues_009": ("Wat zegt de Koran over het bespotten van andere mensen?", ["Het is verboden: de bespotten kunnen beter zijn dan de spotters", "Het is toegestaan onder vrienden", "Het is toegestaan als het grappig is", "Het is voorbehouden aan dichters"], "«Laat geen volk een ander volk bespotten: misschien zijn zij beter dan zij.»"),
"virtues_010": ("Wat belooft Allah volgens de Koran aan wie dankbaar is?", ["Hij zal hem zeker meer geven", "Een lang leven", "Onmiddellijke rijkdom", "Een reis"], "«Als jullie dankbaar zijn, zal Ik jullie zeker meer geven.»"),
"virtues_011": ("Hoe zullen de geduldigen (sabirun) volgens de Koran hun beloning krijgen?", ["Volledig, zonder maat", "In één keer", "Na veertig dagen", "Naar hun rijkdom"], "«De geduldigen zullen hun beloning volledig krijgen, zonder afrekening.»"),
"virtues_012": ("«Eet en drink, maar…»: hoe gaat dit vers verder?", ["Verspil niet", "Deel niet", "Spreek niet", "Ga niet naar buiten"], "«Eet en drink, maar wees niet buitensporig: Allah houdt niet van de verspillers.»"),
"virtues_013": ("Welk vers, vaak gereciteerd in de vrijdagpreek, vat samen wat Allah gebiedt?", ["«Allah gebiedt rechtvaardigheid en goed gedrag»", "«Allah gebiedt handel»", "«Allah gebiedt reizen»", "«Allah gebiedt stilte»"], "«Allah gebiedt rechtvaardigheid, goed gedrag en vrijgevigheid jegens verwanten…»: elke vrijdag gereciteerd."),
"virtues_014": ("Tegen wie opent soera Al-Mutaffifin met «Wee…»?", ["Zij die bedriegen met maat en gewicht", "Zij die slapen", "Zij die reizen", "Zij die zwijgen"], "«Wee de bedriegers: die volle maat eisen wanneer zij ontvangen, maar minder geven wanneer zij voor anderen meten.»"),
"virtues_015": ("Hoe moeten de wees en degene die vraagt volgens soera Ad-Duha behandeld worden?", ["Noch onderdrukt, noch weggestuurd", "Genegeerd", "Naar anderen gestuurd", "Later aangesproken"], "«Wat de wees betreft, onderdruk hem niet; en wat degene betreft die vraagt, stoot hem niet af.»"),
"virtues_016": ("Hoe gebiedt de Koran tot de mensen te spreken?", ["Met goede woorden", "Met zeer zachte stem", "Zo weinig mogelijk", "Alleen tot verwanten"], "«…en spreek goede woorden tot de mensen»: vriendelijk spreken is zelf aanbidding."),
"virtues_017": ("Wat zegt Luqman in zijn advies aan zijn zoon over lopen en hoogmoed?", ["Loop niet hoogmoedig over de aarde", "Loop altijd snel", "Loop alleen 's nachts", "Loop nooit alleen"], "«Wend je wang niet uit hoogmoed van de mensen af, en loop niet hoogmoedig over de aarde.»"),
"virtues_018": ("Waarnaar worden daden beoordeeld, volgens de allereerste hadith van de verzameling van al-Bukhari?", ["Intenties", "Resultaten", "Gewoonten", "Getuigen"], "«Daden zijn slechts naar de intenties, en ieder mens krijgt alleen wat hij beoogde.»"),
"virtues_019": ("Waartoe leidt waarachtigheid (sidq) volgens een hadith in al-Bukhari?", ["Tot rechtschapenheid, en rechtschapenheid leidt naar het Paradijs", "Tot rijkdom", "Tot roem", "Tot kracht"], "«Waarachtigheid leidt tot rechtschapenheid, en rechtschapenheid leidt naar het Paradijs; liegen leidt tot verdorvenheid, en verdorvenheid leidt naar het Vuur.»"),
"virtues_020": ("Wat zijn volgens een authentieke hadith de drie tekenen van een huichelaar?", ["Hij liegt als hij spreekt, breekt zijn belofte en verraadt vertrouwen", "Hij slaapt, eet en praat te veel", "Hij reist, handelt en zingt", "Hij bidt weinig, vast weinig en leest weinig"], "«De tekenen van een huichelaar zijn drie: als hij spreekt liegt hij, als hij belooft breekt hij het, en als hij vertrouwd wordt verraadt hij.»"),
"virtues_021": ("Een man vroeg de Profeet ﷺ om advies; wat herhaalde hij verschillende keren tegen hem?", ["«Word niet boos»", "«Reis veel»", "«Eet weinig»", "«Spreek luid»"], "De man zei: «Geef mij raad.» Hij antwoordde: «Word niet boos.» De man vroeg opnieuw, en hij herhaalde: «Word niet boos.»"),
"virtues_022": ("Wie is volgens de Profeet ﷺ werkelijk sterk?", ["Wie zichzelf beheerst wanneer hij boos is", "Wie wint bij het worstelen", "Wie de zwaarste lasten draagt", "Wie het snelst rent"], "«De sterke is niet degene die anderen overwint bij het worstelen; de sterke is degene die zichzelf beheerst wanneer hij boos is.»"),
"virtues_023": ("Waarvan is schaamte (haya') volgens een hadith in al-Bukhari een deel?", ["Van het geloof", "Van zwakte", "Van rijkdom", "Van laakbare verlegenheid"], "Toen hij een man zijn broeder om zijn schaamte zag berispen, zei de Profeet ﷺ: «Laat hem, want schaamte is een deel van het geloof.»"),
"virtues_024": ("Wat zei de Profeet ﷺ tegen een man die opschepte dat hij geen van zijn tien kinderen ooit had gekust?", ["«Wie geen barmhartigheid toont, zal geen barmhartigheid ontvangen»", "«Je hebt gelijk»", "«Kinderen doen er niet toe»", "«Dat is een privézaak»"], "De Profeet ﷺ kuste zijn kleinkinderen; tegen Al-Aqra', die verbaasd was, antwoordde hij: «Man la yarham la yurham.»"),
"virtues_025": ("Voor welke daad werd een man volgens een hadith in al-Bukhari vergeven?", ["Voor het te drinken geven van een dorstige hond", "Voor het bouwen van een put", "Voor het planten van een boom", "Voor het verjagen van een wolf"], "De man daalde in een put af, vulde zijn schoen met water en gaf het aan een hond die hijgde van dorst; Allah vergaf hem."),
"virtues_026": ("Waarom werd een vrouw volgens een authentieke hadith gestraft?", ["Omdat zij een kat opsloot zonder haar te voeden of voedsel te laten zoeken", "Omdat zij een kat verkocht", "Omdat zij een kat uit haar huis verjoeg", "Omdat zij te veel katten adopteerde"], "«Een vrouw werd gestraft vanwege een kat die zij had opgesloten tot zij stierf: zij voedde haar niet en liet haar niet eten van de schepselen van de aarde.»"),
"virtues_027": ("Over wie zei de Profeet ﷺ dat Jibril hem zo vaak bleef aanbevelen dat hij dacht dat hij hem tot erfgenaam zou maken?", ["De buur", "De gast", "De wees", "De reiziger"], "«Jibril bleef mij de buur aanbevelen, totdat ik dacht dat hij hem tot erfgenaam zou maken.»"),
"virtues_028": ("Hoeveel rechten heeft een moslim volgens een hadith in al-Bukhari op zijn medemoslim?", ["Vijf", "Drie", "Zeven", "Tien"], "«De groet beantwoorden, de zieke bezoeken, de begrafenis volgen, de uitnodiging aanvaarden, en antwoorden aan wie niest.»"),
"virtues_029": ("Wat antwoordde de Profeet ﷺ op de vraag «Welke islam is het beste?»", ["Mensen voeden en groeten wie je kent en wie je niet kent", "Moskeeën bouwen", "Veel reizen", "Weinig spreken"], "«Anderen voeden, en de vredesgroet geven aan wie je kent en wie je niet kent.»"),
"virtues_030": ("Waarmee vergelijkt de Profeet ﷺ de gelovigen in hun liefde en onderlinge steun?", ["Met één lichaam: als één ledemaat lijdt, blijft het hele lichaam wakker met koorts", "Met een bos", "Met een karavaan", "Met een kudde"], "«De gelovigen zijn in hun onderlinge liefde, barmhartigheid en mededogen als één lichaam.»"),
"virtues_031": ("Wat is volgens de Profeet ﷺ «de meest leugenachtige spraak»?", ["Achterdocht (zann)", "Poëzie", "Grappen maken", "Stilte"], "«Pas op voor achterdocht, want achterdocht is de meest leugenachtige spraak.»"),
"virtues_032": ("Hoeveel dagen mag een moslim volgens een authentieke hadith zijn broeder hoogstens mijden?", ["Drie dagen", "Zeven dagen", "Een maand", "Een jaar"], "«Het is een man niet toegestaan zijn broeder langer dan drie nachten te mijden… en de beste van de twee is degene die als eerste groet.»"),
"virtues_033": ("Wat is volgens de Profeet ﷺ de waarde van elke goede daad, hoe klein ook?", ["Zij is een liefdadigheid (sadaqa)", "Zij telt niet", "Zij is een dinar waard", "Zij vervangt het gebed"], "«Elke goede daad is een liefdadigheid.»"),
"virtues_034": ("Wat is volgens een hadith in Sahih Muslim de nederigste tak van het geloof?", ["Iets schadelijks van de weg verwijderen", "Een moskee bouwen", "Een juz' reciteren", "Een dag vasten"], "«Het geloof heeft zeventig-en-nog-wat takken: de hoogste is 'la ilaha illa Allah', de laagste is iets schadelijks van de weg verwijderen; en schaamte is een tak van het geloof.»"),
"virtues_035": ("Reinheid (tahara) is volgens een hadith in Sahih Muslim…?", ["De helft van het geloof", "Een derde van het geloof", "Een tiende van het geloof", "Los van het geloof"], "«Reinheid is de helft van het geloof, en 'al-hamdu li-Llah' vult de weegschaal.»"),
"virtues_036": ("De Profeet ﷺ zei: «De religie is nasiha (oprechte raad)»: jegens wie?", ["Jegens Allah, Zijn Boek, Zijn Boodschapper, de leiders en alle moslims", "Alleen jegens zichzelf", "Jegens de rijken", "Jegens vreemden"], "Zij vroegen: «Jegens wie?» Hij zei: «Jegens Allah, Zijn Boek, Zijn Boodschapper, de leiders van de moslims en hun gewone mensen.»"),
"virtues_037": ("Waarnaar kijkt Allah volgens een hadith in Sahih Muslim bij Zijn dienaren?", ["Naar hun harten en hun daden", "Naar hun uiterlijk", "Naar hun rijkdom", "Naar hun aantal"], "«Allah kijkt niet naar jullie lichamen of jullie uiterlijk, maar Hij kijkt naar jullie harten en jullie daden.»"),
"virtues_038": ("Wat doet Allah volgens een hadith in Sahih Muslim voor wie een gelovige van een moeilijkheid van deze wereld verlost?", ["Hij verlost hem van een moeilijkheid op de Dag der Opstanding", "Hij maakt hem rijk", "Hij schenkt hem een lang leven", "Hij maakt hem beroemd"], "«Wie een gelovige van een moeilijkheid van deze wereld verlost, Allah zal hem van een moeilijkheid op de Dag der Opstanding verlossen.»"),
"virtues_039": ("Wat doet Allah volgens de Profeet ﷺ voor wie een weg bewandelt op zoek naar kennis?", ["Hij maakt voor hem een weg naar het Paradijs gemakkelijk", "Hij ontslaat hem van het gebed", "Hij maakt hem rijk", "Hij maakt hem koning"], "«Wie een weg bewandelt op zoek naar kennis, Allah maakt voor hem een weg naar het Paradijs gemakkelijk.»"),
"virtues_040": ("Wie is volgens een hadith in al-Bukhari «de beste van jullie»?", ["Wie de Koran leert en hem onderwijst", "Wie het beste spreekt", "Wie het meeste bezit", "Wie het meeste reist"], "«De beste van jullie is degene die de Koran leert en hem onderwijst.»"),
"virtues_041": ("Hoe definieerde de Profeet ﷺ hoogmoed (kibr)?", ["De waarheid verwerpen en op mensen neerkijken", "Mooie kleren dragen", "Mooie schoenen mooi vinden", "Snel lopen"], "Tegen de man die van mooie kleren hield zei hij: «Allah is mooi en houdt van schoonheid. Hoogmoed is de waarheid verwerpen en mensen minachten.»"),
"virtues_042": ("Welke twee zegeningen weten veel mensen volgens een hadith in al-Bukhari niet te benutten?", ["Gezondheid en vrije tijd", "Geld en roem", "Kracht en schoonheid", "Familie en vrienden"], "«Er zijn twee zegeningen waarin veel mensen verliezen: gezondheid en vrije tijd.»"),
"virtues_043": ("Vul deze hadith aan: «De gelovige wordt niet tweemaal gestoken…»", ["«…uit hetzelfde hol»", "«…door dezelfde schorpioen»", "«…op dezelfde dag»", "«…door dezelfde bij»"], "«La yuldaghu al-mu'minu min juhrin wahidin marratayn»: de gelovige leert van zijn fouten."),
"virtues_044": ("Waarmee vergelijkt de Profeet ﷺ de goede metgezel, in tegenstelling tot de smid?", ["Met de verkoper van muskus", "Met de bakker", "Met de herder", "Met de stoffenhandelaar"], "«De goede metgezel is als de drager van muskus: hij geeft je ervan, of je koopt van hem, of je ruikt zijn geur; de slechte is als de blaasbalg van de smid.»"),
"virtues_045": ("Waarvoor is ieder van ons volgens een hadith in al-Bukhari verantwoordelijk, «als een herder»?", ["Voor degenen die aan onze zorg zijn toevertrouwd", "Voor het weer", "Voor de sterren", "Voor de oogsten van anderen"], "«Ieder van jullie is een herder, en ieder is verantwoordelijk voor zijn kudde»: de heerser voor zijn volk, de man voor zijn gezin, de vrouw voor haar huishouden."),
"virtues_046": ("Wat gebeurt er volgens de Koran als men het kwaad afweert met wat beter is?", ["Degene die een vijand was wordt als een warme vriend", "Het kwaad verdwijnt van de aarde", "Men wordt rijk", "Er verandert niets"], "«Weer het kwaad af met wat beter is, en degene tussen wie en jou vijandschap was zal worden alsof hij een warme vriend is» (41:34)."),
"virtues_047": ("Hoe antwoorden «de dienaren van de Meest Barmhartige» de onwetenden die hen uitdagen, volgens soera Al-Furqan?", ["Zij zeggen: «Vrede!»", "Zij antwoorden met woede", "Zij bespotten hen", "Zij slaan hen"], "«De dienaren van de Meest Barmhartige lopen nederig over de aarde, en wanneer de onwetenden hen aanspreken, zeggen zij: Vrede!» (25:63)."),
"virtues_048": ("Wat zegt de Koran over het verbond (een belofte, een toezegging)?", ["«Kom het verbond na, want over het verbond zal worden gevraagd»", "«Een belofte bindt niemand»", "«Beloof alleen de rijken»", "«Beloof nooit»"], "«En kom het verbond na; voorwaar, over het verbond zal worden gevraagd» (17:34)."),
"virtues_049": ("Van wie zegt de Koran dat zij «de broeders van de duivels» zijn?", ["De verkwisters", "De reizigers", "De kooplieden", "De dichters"], "«De verkwisters zijn de broeders van de duivels, en de Duivel is ondankbaar jegens zijn Heer» (17:27)."),
"virtues_050": ("Wat zijn de «twee woorden licht op de tong, zwaar op de weegschaal, en geliefd bij de Meest Barmhartige»?", ["«Subhana Allahi wa bi-hamdih, subhana Allahi al-'Azim»", "«Allahu akbar, al-hamdu li-Llah»", "«La ilaha illa Allah, Muhammad rasulu Allah»", "«Bismi Allah, ma sha'a Allah»"], "«Twee woorden licht op de tong, zwaar op de weegschaal, geliefd bij de Meest Barmhartige: Glorie zij Allah en lof zij Hem; glorie zij Allah de Geweldige.»"),
}
